use vstd::prelude::*;

verus! {

spec fn split_append(s: Seq<i32>, n: nat) -> Seq<i32> {
    s.subrange(n, s.len()) + s.subrange(0, n)
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list@.len() > 0,
        0 < n,
        n < list@.len(),
    ensures
        new_list@ == split_append(list@, n as nat),
        new_list@.len() == list@.len(),
{
    // Assumptions from the problem:
    // - list.len() > 0
    // - 0 < n < list.len()
    let len = list.len();
    assert!(len > 0, "list must be non-empty");
    assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);

    // Bridge the slice operations to the Seq postcondition.
    assert(new_list@ == list@.subrange(n as nat, list@.len()) + list@.subrange(0, n as nat));
    assert(new_list@.len() == list@.len());
    new_list
}

} // verus!

